fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn ring_color(r: i32) -> i32 {
    match r {
        40..=60 => 0x00cc66,
        20..40 => 0xffaa00,
        _ => 0xff3333,
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1);
        host::display::state_set(2, 240);
        host::display::state_set(3, 0);
        host::display::state_set(5, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    let score: i32 = host::display::state_get(3);
    if host::display::state_get(5) == 1 {
        host::display::clear(0x101010);
        host::display::draw_string(110, 180, "IT SLIPPED AWAY", 0xff4040, 3);
        host::display::draw_string(130, 250, "HITS", 0x808080, 2);
        host::display::draw_number(230, 244, score, 0xffffff, 3);
        host::display::draw_string(130, 284, "BEST", 0x808080, 2);
        host::display::draw_number(230, 278, host::display::state_get(4), 0x00ff88, 3);
        host::display::draw_string(130, 350, "TAP TO CHASE", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let round: i32 = host::display::state_get(1);
        let cx: i32 = 60 + hash(round * 3) % (w - 120);
        let cy: i32 = 80 + hash(round * 3 + 1) % (h - 160);
        let mut rf: i32 = host::display::state_get(2);
        let mut shrink: i32 = 2 + score / 3;
        if shrink > 8 { shrink = 8; }
        rf = rf - shrink;
        let r: i32 = rf / 4;
        if r <= 6 {
            host::display::state_set(5, 1);
            if score > host::display::state_get(4) {
                host::display::state_set(4, score);
            }
        }
        if tap {
            let dx: i32 = host::display::pointer_x() - cx;
            let dy: i32 = host::display::pointer_y() - cy;
            if dx * dx + dy * dy <= r * r {
                host::display::state_set(3, score + 1);
                host::display::state_set(1, round + 1);
                rf = 240;
            }
        }
        host::display::state_set(2, rf);
        host::display::clear(0x0c0c14);
        host::display::fill_rect(cx - r, cy - r, 2 * r, 2 * r, ring_color(r));
        let inner: i32 = r * 2 / 3;
        host::display::fill_rect(cx - inner, cy - inner, 2 * inner, 2 * inner, 0x0c0c14);
        host::display::fill_rect(cx - 3, cy - 3, 6, 6, 0xffffff);
        host::display::draw_string(8, 8, "HITS", 0x808080, 2);
        host::display::draw_number(90, 8, score, 0xffffff, 2);
    }
    host::display::present();
}
